mapper.select:
SELECT game_id AS "gameId", step_id AS "stepId", repeat_scope_type_id AS "repeatScopeTypeId", repeat_count AS "repeatCount", repeat_tag AS "repeatTag", trigger_state_key AS "triggerStateKey", threshold AS "threshold", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.repeat_effect_details WHERE game_id = #{gameId}
AND step_id = #{stepId}
ORDER BY step_id

mapper.delete:
DELETE FROM public.repeat_effect_details
WHERE game_id = #{gameId}
  AND step_id = #{stepId}
